#!/usr/bin/env Rscript
# Exact additive decomposition of frozen outer-held-out molecular score changes.
# This script reads only the portable model bundle generated by train_models.R.

args <- commandArgs(trailingOnly = TRUE)
option <- function(name, default = NULL) {
  index <- match(name, args)
  if (is.na(index)) return(default)
  if (index == length(args) || startsWith(args[index + 1L], "--"))
    stop("Missing value for ", name)
  args[index + 1L]
}
model_run <- option("--model-run")
output <- option("--output")
rule <- option("--rule", "lambda.1se")
if (is.null(model_run) || is.null(output)) {
  stop("Usage: Rscript scripts/extract_contributions.R --model-run DIR --output DIR [--rule lambda.1se]")
}
if (!requireNamespace("jsonlite", quietly = TRUE)) stop("Install the R package jsonlite")
model_run <- normalizePath(model_run, mustWork = TRUE)
dir.create(output, recursive = TRUE, showWarnings = FALSE)

write_csv <- function(value, name) {
  write.table(value, file.path(output, name), sep = ",", row.names = FALSE,
              col.names = TRUE, quote = TRUE, na = "")
}
required <- function(value, columns, description) {
  missing <- setdiff(columns, names(value))
  if (length(missing)) stop(description, " lacks: ", paste(missing, collapse = ", "))
}
prediction_frame <- function(value) {
  # Saved model objects preserve the original internal names; ensemble CSVs use
  # the public normalized names. Accept both without changing their values.
  if ("sample_id" %in% names(value)) value$SUBJID <- as.character(value$sample_id)
  if ("week" %in% names(value)) value$Week <- value$week
  required(value, c("SUBJID", "Week", "rule", "predicted_log_homa"), "Prediction table")
  value$SUBJID <- as.character(value$SUBJID)
  value
}
get_prediction <- function(value, sample_ids, week_value) {
  value <- prediction_frame(value)
  value <- value[value$rule == rule, , drop = FALSE]
  key <- paste(value$SUBJID, value$Week)
  if (anyDuplicated(key)) stop("Duplicate participant/visit predictions within a frozen model")
  result <- value$predicted_log_homa[match(paste(sample_ids, week_value), key)]
  if (any(!is.finite(result))) stop("Missing or nonfinite held-out predictions")
  result
}

dat <- readRDS(file.path(model_run, "analysis_data.rds"))
folds <- as.matrix(readRDS(file.path(model_run, "outer_folds.rds")))
annotations <- read.csv(file.path(model_run, "feature_annotations.csv"),
                        stringsAsFactors = FALSE, check.names = FALSE)
required(annotations, c("feature_id", "omics", "label"), "Feature annotations")
if (anyDuplicated(annotations$feature_id)) stop("Duplicate feature identifiers")
feature_ids <- as.character(annotations$feature_id)
required(dat$data, c("SUBJID", "Week", "Trial", "Arm", "Sex", "Age"), "Analysis data")
dat$data$SUBJID <- as.character(dat$data$SUBJID)
if (anyDuplicated(paste(dat$data$SUBJID, dat$data$Week))) stop("Duplicate participant/visit input rows")
if (is.null(rownames(folds)) || anyDuplicated(rownames(folds)) || anyNA(folds))
  stop("Outer fold plan requires unique participant row names and no missing assignments")
if (!all(feature_ids %in% colnames(dat$x))) stop("Molecular input matrix lacks annotated features")
n_repeats <- ncol(folds)
n_folds <- max(folds)
if (n_repeats < 1L || n_folds < 2L || !all(folds %in% seq_len(n_folds)))
  stop("Invalid outer fold assignments")
if (!all(vapply(seq_len(n_repeats), function(r) setequal(folds[, r], seq_len(n_folds)), logical(1))))
  stop("Every repetition must contain every outer fold")

ensemble <- prediction_frame(read.csv(file.path(model_run, "participant_predictions.csv"),
                                      colClasses = c(sample_id = "character"), check.names = FALSE))
required(ensemble, "score", "Ensemble predictions")
score_labels <- unique(ensemble$score)
mol_label <- intersect(c("mol-HOMA-IR", "PhenoIR", "mol"), score_labels)
if (length(mol_label) != 1L) stop("Cannot identify the mol-HOMA-IR ensemble in participant_predictions.csv")
ensemble <- ensemble[ensemble$score == mol_label & ensemble$rule == rule, , drop = FALSE]
if ("n_repeats" %in% names(ensemble) && any(ensemble$n_repeats != n_repeats))
  stop("Every ensemble prediction must include all repetitions")
ids <- sort(intersect(ensemble$SUBJID[ensemble$Week == 0], ensemble$SUBJID[ensemble$Week == 24]))
ids <- ids[ids %in% rownames(folds)]
if (!length(ids)) stop("No paired W0/W24 mol-HOMA-IR predictions")
key <- paste(dat$data$SUBJID, dat$data$Week)
i0 <- match(paste(ids, 0), key)
i24 <- match(paste(ids, 24), key)
if (anyNA(c(i0, i24))) stop("Paired prediction participants lack W0/W24 molecular input")

contribution <- change <- matrix(0, length(ids), length(feature_ids),
                                dimnames = list(ids, feature_ids))
counts <- integer(length(ids))
selection <- matrix(0, length(feature_ids), n_repeats * n_folds,
                    dimnames = list(feature_ids, NULL))
audits <- list()
for (r in seq_len(n_repeats)) {
  for (f in seq_len(n_folds)) {
    heldout <- rownames(folds)[folds[, r] == f]
    ix <- which(ids %in% heldout)
    stack <- readRDS(file.path(model_run, "models", sprintf("PhenoIR_direct_r%02d_f%02d.rds", r, f)))
    if (is.null(stack$model$training_ids)) stop("Frozen integration model lacks training IDs for leakage verification")
    if (any(heldout %in% stack$model$training_ids)) stop("Training/held-out overlap in integration model")
    weights <- stack$model$weights[stack$model$weights$rule == rule, , drop = FALSE]
    if (nrow(weights) != 1L) stop("Integration weights missing or duplicated for selected rule")
    cc <- zz <- matrix(0, length(ix), length(feature_ids), dimnames = list(NULL, feature_ids))
    base_errors <- numeric()
    for (platform in c("MetIR", "ProtIR")) {
      object <- readRDS(file.path(model_run, "models", sprintf("%s_direct_r%02d_f%02d.rds", platform, r, f)))
      model <- object$model
      prep <- model$prep
      if (is.null(model$training_ids)) stop("Frozen base model lacks training IDs for leakage verification")
      if (any(heldout %in% model$training_ids)) stop("Training/held-out overlap in base model")
      if (!identical(prep$variant, "direct") || !is.null(prep$x_beta))
        stop("This additive extractor supports only direct, nonresidual molecular models")
      if (!all(prep$ids %in% feature_ids)) stop("Frozen model contains unannotated features")
      if (!(rule %in% colnames(model$beta))) stop("Selected penalty rule absent from base coefficients")
      if (any(!is.finite(prep$scale)) || any(prep$scale <= 0)) stop("Invalid frozen feature scales")
      # Base coefficients are fitted to the standardized response. Multiplication
      # by y_sd restores units of log HOMA-IR per training-fold feature SD.
      beta <- model$beta[-1, rule] * prep$y_sd
      if (length(beta) != length(prep$ids)) stop("Coefficient/preprocessing feature mismatch")
      weight <- if (platform == "MetIR") weights$beta_met else weights$beta_prot
      effective <- weight * beta
      if (any(!is.finite(effective))) stop("Nonfinite effective molecular coefficients")
      selection[prep$ids, (r - 1L) * n_folds + f] <- effective
      if (!length(ix)) next
      transform <- function(rows) {
        # dat$x is already on the same transformed scale as model training.
        x <- dat$x[rows, prep$ids, drop = FALSE]
        bad <- which(!is.finite(x), arr.ind = TRUE)
        if (nrow(bad)) x[bad] <- prep$medians[bad[, 2]]
        sweep(sweep(x, 2, prep$center, "-"), 2, prep$scale, "/")
      }
      dz <- transform(i24[ix]) - transform(i0[ix])
      base_contribution <- sweep(dz, 2, beta, "*")
      delta <- get_prediction(object$predictions, ids[ix], 24) - get_prediction(object$predictions, ids[ix], 0)
      err <- max(abs(rowSums(base_contribution) - delta))
      if (!is.finite(err) || err >= 1e-10) stop("Base-model change reconstruction failed")
      base_errors <- c(base_errors, err)
      cc[, prep$ids] <- weight * base_contribution
      zz[, prep$ids] <- dz
    }
    if (length(ix)) {
      delta <- get_prediction(stack$predictions, ids[ix], 24) - get_prediction(stack$predictions, ids[ix], 0)
      err <- max(abs(rowSums(cc) - delta))
      if (!is.finite(err) || err >= 1e-10) stop("Integrated model change reconstruction failed")
      contribution[ix, ] <- contribution[ix, , drop = FALSE] + cc
      change[ix, ] <- change[ix, , drop = FALSE] + zz
      counts[ix] <- counts[ix] + 1L
    } else {
      err <- 0
    }
    audits[[length(audits) + 1L]] <- data.frame(
      repetition = r, fold = f, n_paired = length(ix),
      base_max_reconstruction_error = if (length(base_errors)) max(base_errors) else 0,
      integrated_reconstruction_error = err, training_overlap = 0L)
  }
  cat("Extracted frozen contributions, repetition", r, "of", n_repeats, "\n")
}
if (!all(counts == n_repeats)) stop("Not every participant has one held-out contribution per repetition")
contribution <- contribution / n_repeats
change <- change / n_repeats
baseline <- get_prediction(ensemble, ids, 0)
followup <- get_prediction(ensemble, ids, 24)
final_error <- max(abs(rowSums(contribution) - (followup - baseline)))
if (!is.finite(final_error) || final_error >= 1e-10) stop("Ensemble mean change reconstruction failed")

selection_by_repeat <- do.call(rbind, lapply(seq_len(n_repeats), function(r) {
  columns <- ((r - 1L) * n_folds + 1L):(r * n_folds)
  data.frame(feature_id = feature_ids, repetition = r,
             n_selected = rowSums(selection[, columns, drop = FALSE] != 0), n_folds = n_folds)
}))
phenotype <- dat$data[i0, , drop = FALSE]
clinical <- data.frame(sample_id = ids, trial = phenotype$Trial, arm = phenotype$Arm,
                       sex = phenotype$Sex, age = phenotype$Age,
                       baseline_mol = baseline, followup_mol = followup,
                       stringsAsFactors = FALSE)
write_csv(data.frame(sample_id = ids, contribution, check.names = FALSE), "participant_contributions.csv")
write_csv(data.frame(sample_id = ids, change, check.names = FALSE), "participant_molecular_changes.csv")
write_csv(clinical, "participant_scores_covariates.csv")
write_csv(annotations, "feature_annotations.csv")
write_csv(selection_by_repeat, "selection_by_repeat.csv")
write_csv(data.frame(feature_id = feature_ids, n_selected = rowSums(selection != 0),
                     n_models = ncol(selection)), "model_selection.csv")
write_csv(do.call(rbind, audits), "prediction_reconstruction_audit.csv")
jsonlite::write_json(list(
  n_paired = length(ids), n_baseline_fold_participants = nrow(folds),
  n_features = length(feature_ids), repetitions = n_repeats, outer_folds = n_folds,
  models = n_repeats * n_folds, rule = rule,
  heldout_predictions_per_participant = n_repeats,
  mean_score_change_reconstruction_error = final_error,
  coefficients = "integration weight * elastic-net coefficient * training response SD",
  participant_contribution = "Mean over repetitions of effective coefficient times frozen standardized W24-W0 feature change",
  individual_data_warning = "These intermediate outputs contain participant-level data; do not upload them to a public repository"
), file.path(output, "extraction_validation.json"), pretty = TRUE, auto_unbox = TRUE)
cat("Saved contribution inputs for", length(ids), "paired participants and", length(feature_ids), "features.\n")
